// Package emoji is a searchable list of emoji: Unicode's names plus CLDR's
// English keywords (so "laugh" finds 😂), embedded from emoji.tsv. That file
// is generated by ./gen (`just emoji`); the data is © Unicode, Inc., see
// UNICODE-LICENSE.
package emoji

import (
	_ "embed" // emoji.tsv
	"slices"
	"strings"
	"sync"

	"github.com/wasichu/go-whassup/internal/fuzzy"
)

//go:embed emoji.tsv
var data string

// Emoji is one emoji with its Unicode name and search keywords.
type Emoji struct {
	Glyph    string
	Name     string
	Keywords []string
}

var all = sync.OnceValue(func() []Emoji {
	var out []Emoji
	for line := range strings.Lines(data) {
		line = strings.TrimSuffix(line, "\n")
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.Split(line, "\t")
		if len(parts) != 3 {
			continue
		}
		e := Emoji{Glyph: parts[0], Name: parts[1]}
		if parts[2] != "" {
			e.Keywords = strings.Split(parts[2], "|")
		}
		out = append(out, e)
	}
	return out
})

// All lists every emoji in Unicode's order (smileys first).
func All() []Emoji { return all() }

// Search returns up to limit emoji matching query, best first. Matches rank
// by kind: a whole word of the name ("heart" → red heart), then an exact
// keyword ("laugh" → 😂), a word of the name starting with the query, a
// keyword starting with it, and finally a fuzzy match on the name; shorter
// names, then Unicode's order, break ties. An empty query lists emoji in
// Unicode's order.
func Search(query string, limit int) []Emoji {
	q := strings.ToLower(strings.TrimSpace(query))
	if q == "" {
		return all()[:min(limit, len(all()))]
	}
	type hit struct {
		e          Emoji
		tier, rank int
	}
	var hits []hit
	for i, e := range all() {
		tier, ok := match(q, e)
		if !ok {
			continue
		}
		hits = append(hits, hit{e: e, tier: tier, rank: i})
	}
	slices.SortStableFunc(hits, func(a, b hit) int {
		if a.tier != b.tier {
			return a.tier - b.tier
		}
		if la, lb := len(a.e.Name), len(b.e.Name); la != lb {
			return la - lb
		}
		return a.rank - b.rank
	})
	out := make([]Emoji, 0, min(limit, len(hits)))
	for _, h := range hits[:min(limit, len(hits))] {
		out = append(out, h.e)
	}
	return out
}

// match reports how well q (lower case) matches e: a lower tier is better.
func match(q string, e Emoji) (tier int, ok bool) {
	words := strings.FieldsFunc(strings.ToLower(e.Name), func(r rune) bool { return r == ' ' || r == ':' || r == ',' })
	switch {
	case slices.Contains(words, q):
		return 0, true
	case slices.Contains(e.Keywords, q):
		return 1, true
	case slices.ContainsFunc(words, func(w string) bool { return strings.HasPrefix(w, q) }):
		return 2, true
	case slices.ContainsFunc(e.Keywords, func(k string) bool { return strings.HasPrefix(k, q) }):
		return 3, true
	}
	if _, ok := fuzzy.Score(q, e.Name); ok && len(q) > 2 {
		return 4, true // short fuzzy queries match nearly everything
	}
	return 0, false
}
